import java.util.*;

public class Main {
    static int smallestCommonElement(int[][] mat) {
        int m = mat.length;
        for (int val : mat[0]) {
            boolean inAll = true;
            for (int r = 1; r < m; r++) {
                boolean found = false;
                for (int v : mat[r]) {
                    if (v == val) { found = true; break; }
                }
                if (!found) { inAll = false; break; }
            }
            if (inAll) return val;
        }
        return -1;
    }

    public static void main(String[] args) {
        System.out.println(smallestCommonElement(new int[][]{{1, 2, 3, 4, 5}, {2, 4, 5, 8, 10}, {3, 5, 7, 9, 11}, {1, 3, 5, 7, 9}}));
        System.out.println(smallestCommonElement(new int[][]{{1, 2, 3}, {2, 3, 4}, {2, 3, 5}}));
    }
}

