def smallest_common_element(mat):
    m = len(mat)
    counts = {}

    for row in mat:
        for val in row:
            counts[val] = counts.get(val, 0) + 1

    best = -1
    for val, c in counts.items():
        if c == m and (best == -1 or val < best):
            best = val

    return best


