import java.util.*;

public class Main {
    static int smallestCommonElement(int[][] mat) {
        int m = mat.length;
        Map<Integer, Integer> counts = new HashMap<>();

        for (int[] row : mat) {
            for (int val : row) {
                counts.merge(val, 1, Integer::sum);
            }
        }

        int best = -1;
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            if (entry.getValue() == m && (best == -1 || entry.getKey() < best)) {
                best = entry.getKey();
            }
        }
        return best;
    }

    public static void main(String[] args) {
        System.out.println(smallestCommonElement(new int[][]{{1, 2, 3, 4, 5}, {2, 4, 5, 8, 10}, {3, 5, 7, 9, 11}, {1, 3, 5, 7, 9}}));
        System.out.println(smallestCommonElement(new int[][]{{1, 2, 3}, {2, 3, 4}, {2, 3, 5}}));
    }
}

