#include <bits/stdc++.h>
using namespace std;

int smallestCommonElement(vector<vector<int>>& mat) {
    int m = mat.size();
    unordered_map<int, int> counts;

    for (auto& row : mat) {
        for (int val : row) {
            counts[val]++;
        }
    }

    int best = -1;
    for (auto& [val, c] : counts) {
        if (c == m && (best == -1 || val < best)) {
            best = val;
        }
    }
    return best;
}

int main() {
    vector<vector<int>> mat1 = {{1, 2, 3, 4, 5}, {2, 4, 5, 8, 10}, {3, 5, 7, 9, 11}, {1, 3, 5, 7, 9}};
    cout << smallestCommonElement(mat1) << endl;
    vector<vector<int>> mat2 = {{1, 2, 3}, {2, 3, 4}, {2, 3, 5}};
    cout << smallestCommonElement(mat2) << endl;
    return 0;
}
